'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './warp-tunnel.css'

export type WarpTunnelProps = React.ComponentPropsWithoutRef<'div'> & {
    color?: string
    /** Number of frames in flight. */
    rings?: number
    /** Seconds for a frame to reach you. Keep it slow: zooming motion can trigger vestibular discomfort. */
    speed?: number
    paused?: boolean
}

// Rounded frames rushing toward the viewer, like flying down a tunnel.
const WarpTunnel = ({ color = 'rgba(167, 139, 250, 0.6)', rings = 10, speed = 6, paused = false, className, style, children, ...props }: WarpTunnelProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-warp', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-warp-color': color, '--rad-fx-warp-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-warp-layer" aria-hidden="true">
            {Array.from({ length: rings }, (_, i) => (
                <span key={i} className="rad-fx-warp-ring" style={{ animationDelay: `calc(var(--rad-fx-warp-speed, 6s) * ${(-i / rings).toFixed(3)})`, '--rad-fx-warp-rest': (0.15 + (i / rings) * 0.85).toFixed(2) } as React.CSSProperties} />
            ))}
        </div>
        <div className="rad-fx-warp-content">{children}</div>
    </div>
}

export default WarpTunnel

.rad-fx-warp {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-warp-layer {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
}

.rad-fx-warp-content { position: relative; }

.rad-fx-warp[data-state='paused'] .rad-fx-warp-layer,
.rad-fx-warp[data-state='paused'] .rad-fx-warp-layer * { animation-play-state: paused !important; }

.rad-fx-warp-ring {
    position: absolute;
    left: 50%;
    top: 50%;
    width: 100%;
    height: 100%;
    translate: -50% -50%;
    border: 1.5px solid var(--rad-fx-warp-color);
    border-radius: 18%;
    opacity: 0;
    animation: rad-fx-warp var(--rad-fx-warp-speed, 6s) cubic-bezier(0.55, 0, 1, 0.45) infinite;
}

/* Frames start tiny and faint, then accelerate past the viewer. */
@keyframes rad-fx-warp {
    0% { transform: scale(0.02); opacity: 0; }
    20% { opacity: 0.8; }
    100% { transform: scale(1.6); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-warp-ring { animation: none; transform: scale(var(--rad-fx-warp-rest, 0.5)); opacity: calc(0.9 - var(--rad-fx-warp-rest, 0.5) * 0.7); }
}

[data-rad-fx-motion='reduce'] .rad-fx-warp-ring { animation: none; transform: scale(var(--rad-fx-warp-rest, 0.5)); opacity: calc(0.9 - var(--rad-fx-warp-rest, 0.5) * 0.7); }
